;border:1px solid #dce6f1;border-radius:8px;padding:8px 9px;margin-bottom:7px}.uf-upload-row b{font-size:9.5px;color:#173866}.uf-upload-btn{height:34px;padding:0 10px;border:1px solid #c9d8e8;border-radius:6px;font:900 9px Cairo;cursor:pointer}.uf-upload-btn.camera{background:#071f4d;color:#fff;border-color:#071f4d}.uf-upload-btn.device{background:#1769c2;color:#fff;border-color:#1769c2}.uf-upload-input{position:absolute!important;width:1px!important;height:1px!important;opacity:0!important;pointer-events:none!important}.uf-files-summary{margin-top:9px;padding:9px 10px;border:1px solid #dce6f1;border-radius:8px;background:#f8fbff;color:#73849c;font-size:9px}.uf-service-specific-title{font-size:10px;color:#6d809a;margin:-3px 0 10px}.uf-workspace.disabled{opacity:.55;pointer-events:none}@media(max-width:1100px){.uf-workspace{grid-template-columns:1fr;grid-template-areas:"asset" "details"}.uf-asset-results{grid-template-columns:repeat(2,1fr)}}@media(max-width:650px){.uf-mode-grid,.uf-manual-grid,.uf-asset-searchbar{grid-template-columns:1fr}.uf-asset-results{grid-template-columns:1fr}.uf-selected-grid{grid-template-columns:1fr 1fr}.uf-upload-row{grid-template-columns:1fr 1fr}.uf-upload-row b{grid-column:1/-1}}
