 const workspace=document.createElement('div'); workspace.className='uf-workspace'; workspace.id='uf-request-workspace';
 workspace.innerHTML=`<section class="panel uf-asset-pane"><div class="uf-pane-head"><span class="num">4</span><div class="uf-pane-copy"><b>المعدة وبياناتها</b><small>اختر أصلاً من أصول العقد المسجلة لدى UNIFCO أو أضف أصلاً غير مسجل</small></div></div>
