 asset.before(workspace);
 const nativeManual={name:$('manual_name'),type:$('manual_type'),brand:$('manual_brand'),model:$('manual_model'),serial:$('manual_serial')};
 const copy=(from,to)=>from?.addEventListener('input',()=>{if(to){to.value=from.value;to.dispatchEvent(new Event('input',{bubbles:true}))}});
 copy($('ufm-name'),nativeManual.name);copy($('ufm-type'),nativeManual.type);copy($('ufm-brand'),nativeManual.brand);copy($('ufm-model'),nativeManual.model);copy($('ufm-serial'),nativeManual.serial);
 const setMode=m=>{document.querySelectorAll('[data-uf-mode]').forEach(b=>b.classList.toggle('active',b.dataset.ufMode===m));$('uf-registered').style.display=m==='registered'?'block':'none';$('uf-manual').classList.toggle('show',m==='manual'); const nb=asset.querySelector(`.asset-method[data-method="${m==='manual'?'manual':'list'}"]`);nb?.click()};
 document.querySelectorAll('[data-uf-mode]').forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.ufMode)));
