 const syncSelected=()=>{if(!nativeList.value){$('uf-selected').classList.remove('show');return}$('uf-selected').classList.add('show');$('ufs-name').textContent=$('ac-name')?.textContent||nativeList.selectedOptions[0]?.textContent||'—';$('ufs-code').textContent=$('ac-code')?.textContent||nativeList.value||'—';$('ufs-model').textContent=$('ac-model')?.textContent||'—';$('ufs-serial').textContent=$('ac-serial')?.textContent||'—';$('ufs-site').textContent=$('ac-site')?.textContent||$('site_name')?.value||'—'};
 $('uf-asset-search').addEventListener('input',render);nativeList.addEventListener('change',()=>setTimeout(()=>{render();syncSelected()},0));contract?.addEventListener('change',()=>setTimeout(()=>{nativeList.value='';render();syncSelected()},250));new MutationObserver(()=>render()).observe(nativeList,{childList:true,subtree:true});
 $('uf-qr').addEventListener('click',()=>{asset.querySelector('.asset-method[data-method="qr"]')?.click();setTimeout(()=>{document.querySelector('[data-qr-camera],.qr-camera-trigger')?.click();$('asset-key')?.focus()},0)});
