  'quotation:parts':{title:'تفاصيل قطع الغيار والمرفقات',help:'حدد القطع والكميات أو المواصفات المطلوبة',label:'تفاصيل قطع الغيار المطلوبة'},
  'quotation:visit':{title:'تفاصيل الزيارة الفنية والمرفقات',help:'حدد سبب الزيارة ونطاق المعاينة',label:'سبب الزيارة الفنية'},
  'quotation:contract':{title:'تفاصيل عقد الصيانة والمرفقات',help:'حدد نطاق العقد والخدمات المطلوبة',label:'متطلبات عقد الصيانة'},
  'consultation:technical':{title:'تفاصيل الاستشارة والمرفقات',help:'اشرح موضوع الاستشارة الفنية والمتطلبات',label:'موضوع الاستشارة الفنية'}
 };
 const attach=(title,name,report=false)=>`<div class="uf-upload-row"><b>${title}</b><button type="button" class="uf-upload-btn camera" data-uf-file="cam-${name}">📷 تصوير بالكاميرا</button><input class="uf-upload-input" id="cam-${name}" type="file" name="${name}[]" accept="image/*" capture="environment" multiple><button type="button" class="uf-upload-btn device" data-uf-file="dev-${name}">↑ رفع من الجهاز</button><input class="uf-upload-input" id="dev-${name}" type="file" name="${name}[]" accept="${report?'.pdf,.doc,.docx,.xls,.xlsx,image/*':'image/*'}" multiple></div>`;
 const syncDetail=()=>{const c=configs[`${service?.value||'maintenance'}:${subtype?.value||'routine'}`]||configs['maintenance:routine'];$('uf-detail-heading').textContent=c.title;$('uf-detail-help').textContent=c.help;let fields=`<div class="uf-detail-field"><label>${c.label} <span class="req">*</span></label><textarea name="details" id="uf-details" maxlength="500" required placeholder="اكتب وصفاً مختصراً وواضحاً..."></textarea></div>`;if(c.problem)fields+=`<div class="uf-detail-field"><label>نوع المشكلة <span class="req">*</span></label><select name="problem_type" required><option value="">اختر نوع المشكلة</option><option>لا تعمل المعدة</option><option>أداء ضعيف</option><option>صوت / اهتزاز</option><option>تسريب</option><option>كهرباء</option><option>حرارة غير طبيعية</option><option>إنذار / Fault</option><option>أخرى</option></select></div><div class="uf-detail-field"><label>حالة المعدة حالياً</label><div class="uf-chip-row"><button class="uf-chip" type="button" data-chip-name="equipment_state" data-value="متوقفة">متوقفة</button><button class="uf-chip" type="button" data-chip-name="equipment_state" data-value="تعمل جزئياً">تعمل جزئياً</button><button class="uf-chip" type="button" data-chip-name="equipment_state" data-value="تعمل مع وجود مشكلة">تعمل مع وجود مشكلة</button><button class="uf-chip" type="button" data-chip-name="equipment_state" data-value="غير معروف">غير معروف</button></div><input type="hidden" name="equipment_state" id="equipment_state"></div><div class="uf-detail-field"><label>متى بدأت المشكلة؟</label><div class="uf-chip-row"><button class="uf-chip" type="button" data-chip-name="problem_started" data-value="اليوم">اليوم</button><button class="uf-chip" type="button" data-chip-name="problem_started" data-value="منذ عدة أيام">منذ عدة أيام</button><button class="uf-chip" type="button" data-chip-name="problem_started" data-value="متكررة">متكررة</button><button class="uf-chip" type="button" data-chip-name="problem_started" data-value="غير معروف">غير معروف</button></div><input type="hidden" name="problem_started" id="problem_started"></div>`;$('uf-detail-fields').innerHTML=fields;$('uf-upload-rows').innerHTML=attach('صور المشكلة','problem_photos')+attach('صور المعدة','equipment_photos')+attach('تقرير سابق إن وجد','previous_reports',true);document.querySelectorAll('[data-uf-file]').forEach(b=>b.addEventListener('click',()=>$(b.dataset.ufFile)?.click()));document.querySelectorAll('.uf-upload-input').forEach(i=>i.addEventListener('change',summarize));document.querySelectorAll('[data-chip-name]').forEach(b=>b.addEventListener('click',()=>{const n=b.dataset.chipName;document.querySelectorAll(`[data-chip-name="${n}"]`).forEach(x=>x.classList.remove('active'));b.classList.add('active');$(n).value=b.dataset.value}));updateHiddenRequestType()};
